-- Key groups for which-key and the cheatsheet (<leader>?, :Cheatsheet).
-- `prefix` is matched longest-first against each map's lhs. `static` rows are
-- builtins or shell commands worth remembering that aren't nvim maps.
return {
  { prefix = "<leader>b", title = "Buffer", blurb = "Buffer list and switching." },
  { prefix = "<leader>c", title = "Code / LSP", blurb = "LSP actions, diagnostics, formatting (conform), format-on-save toggle.",
    static = { { "K", "Hover (builtin)" } } },
  { prefix = "<leader>d", title = "Debug", blurb = "nvim-dap with dap-ui; F5/F7/F8/F9 drive the session.", },
  { prefix = "<leader>e", title = "Explorer", blurb = "nvim-tree file explorer, plus the database UI." },
  { prefix = "<leader>f", title = "Find", blurb = "Snacks pickers over files, recent, buffers, grep." },
  { prefix = "<leader>gh", title = "Git hunk", blurb = "gitsigns: stage, reset, preview, blame per hunk." },
  { prefix = "<leader>ght", title = "Git hunk toggles", blurb = "gitsigns display toggles." },
  { prefix = "<leader>g", title = "Git", blurb = "lazygit, git pickers, branches, log." },
  { prefix = "<leader>k", title = "Multicursor", blurb = "Neovim 0.13 builtin. Edits replay at every cursor; Esc clears.",
    when = function() return vim.fn.has("nvim-0.13") == 1 end,
    static = { { "Q", "Toggle cursor here (builtin)" }, { "zq{motion}", "Cursor at every {motion} to end of buffer (builtin)" }, { "q=", "Toggle follow mode (builtin)" }, { "gQ", "Restore previous cursors (builtin)" }, { "]C [C", "Next / previous cursor (builtin)" } } },
  { prefix = "<leader>m", title = "Marks (Harpoon)", blurb = "Harpoon quick-file list, plus vim mark deletion.",
    static = { { "m{a-z}", "Set mark (builtin)" }, { "`{mark}", "Jump to mark (builtin)" } } },
  { prefix = "<leader>np", title = "Playwright", blurb = "Neotest runs with Playwright flags (headed, inspector, trace)." },
  { prefix = "<leader>n", title = "Neotest", blurb = "Run, debug and watch tests; [t / ]t jump between failures." },
  { prefix = "<leader>o", title = "Obsidian", blurb = "obsidian.nvim: notes, daily, links, search in the vault." },
  { prefix = "<leader>q", title = "Quickfix", blurb = "Open, close, navigate the quickfix list." },
  { prefix = "<leader>s", title = "Search", blurb = "Snacks pickers: grep, help, keymaps (sk), commands, diagnostics, marks." },
  { prefix = "<leader>t", title = "Tabs", blurb = "Tab pages." },
  { prefix = "<leader>u", title = "UI toggles", blurb = "Zen mode, colorscheme preview, dismiss notifications, reload colorizer, graph view." },
  { prefix = "<leader>U", title = "Unreal", blurb = "UnrealEngine.nvim: build, open editor, generate project files." },
  { prefix = "<leader>v", title = "Visual selection", blurb = "Actions on the current selection." },
  { prefix = "<leader>w", title = "Window", blurb = "Splits, equalise, close, zoom. C-h/j/k/l move between nvim windows and tmux panes." },
  { prefix = "<leader>", title = "Leader (top level)", blurb = "Single-key leader actions: clipboard yank/delete, paste over, pickers.",
    static = { { "<C-a> <C-x>", "Increment / decrement number (builtin)" } } },
  { prefix = "s", title = "Surround", blurb = "mini.surround. Targets: ( [ { < with space, ) ] } > without, quotes, b any bracket, q any quote, f function call, t tag, ? prompt.",
    static = { { "saiw\"", "Surround inner word with quotes" }, { "viwsa(", "Surround selection" } } },
  { prefix = "g", title = "Goto", blurb = "Treesitter textobject jumps, LSP gotos, search variants." },
  { prefix = "[", title = "Previous", blurb = "Jump backward: hunks, diagnostics, failed tests, textobjects.",
    static = { { "gn", "Select next search match (builtin; cgn + . repeats a change)" } } },
  { prefix = "]", title = "Next", blurb = "Jump forward: hunks, diagnostics, failed tests, textobjects." },
  { prefix = "a", title = "Textobjects (around)", blurb = "Treesitter textobjects: function, class, parameter, node. Use after an operator or in visual mode." },
  { prefix = "i", title = "Textobjects (inside)", blurb = "Inner variants of the same textobjects." },
  { prefix = "<F", title = "Function keys", blurb = "Debugger stepping." },
  { prefix = "<", title = "Control / Alt", blurb = "Modifier chords: page centering, Harpoon slots, snippet nodes, semicolon append." },
  { prefix = "", title = "Other", blurb = "Everything else with a description." },
}
